def regex_search(pattern: str, text: str) -> bool:
    pos = [0]

    def peek():
        if pos[0] >= len(pattern):
            return None
        return pattern[pos[0]]

    def advance():
        ch = pattern[pos[0]]
        pos[0] += 1
        return ch

    def parse_alternation():
        branches = [parse_sequence()]
        while peek() == '|':
            advance()
            branches.append(parse_sequence())
        if len(branches) == 1:
            return branches[0]
        return ('alt', branches)

    def parse_sequence():
        elements = []
        while peek() is not None and peek() not in ('|', ')'):
            elem = parse_element()
            if elem is None:
                if peek() in ('*', '+', '?'):
                    raise ValueError("quantifier with no preceding element")
                break
            elements.append(elem)
        return ('seq', elements)

    def parse_element():
        atom = parse_atom()
        if atom is None:
            return None
        if peek() in ('*', '+', '?'):
            if atom[0] in ('start_assert', 'end_assert'):
                raise ValueError("quantifier on assertion")
            quant = advance()
            return ('quant', atom, quant)
        return atom

    def parse_atom():
        ch = peek()
        if ch is None or ch == ')' or ch in ('*', '+', '?'):
            return None
        if ch == '(':
            advance()
            inner = parse_alternation()
            if peek() != ')':
                raise ValueError("Unmatched (")
            advance()
            return ('group', inner)
        elif ch == '[':
            return parse_char_class()
        elif ch == '.':
            advance()
            return ('dot',)
        elif ch == '^':
            advance()
            return ('start_assert',)
        elif ch == '$':
            advance()
            return ('end_assert',)
        elif ch == '\\':
            advance()
            if pos[0] >= len(pattern):
                raise ValueError("Backslash at end")
            c = advance()
            return ('char', c)
        else:
            advance()
            return ('char', ch)

    def parse_char_class():
        advance()
        negated = False
        if peek() == '^':
            advance()
            negated = True
        items = []
        while peek() != ']' and peek() is not None:
            if peek() == '\\':
                advance()
                if peek() is None:
                    raise ValueError("Backslash at end in class")
                c1 = advance()
            else:
                c1 = advance()
            if peek() == '-' and pos[0] + 1 < len(pattern) and pattern[pos[0] + 1] != ']':
                advance()
                if peek() == '\\':
                    advance()
                    if peek() is None:
                        raise ValueError("Backslash at end in class")
                    c2 = advance()
                else:
                    c2 = advance()
                if ord(c1) > ord(c2):
                    raise ValueError("Invalid range")
                items.append(('range', c1, c2))
            else:
                items.append(('char', c1))
        if peek() is None:
            raise ValueError("Unclosed [")
        advance()
        if not items:
            raise ValueError("Empty character class")
        return ('class', items, negated)

    ast = parse_alternation()
    if pos[0] != len(pattern):
        raise ValueError("Unmatched )")

    states = []

    def new_state(d):
        states.append(d)
        return len(states) - 1

    def make_class_pred(items, negated):
        def pred(ch):
            matched = False
            for item in items:
                if item[0] == 'char':
                    if ch == item[1]:
                        matched = True
                        break
                elif item[0] == 'range':
                    if ord(item[1]) <= ord(ch) <= ord(item[2]):
                        matched = True
                        break
            return not matched if negated else matched
        return pred

    def compile_ast(node, next_state):
        tag = node[0]
        if tag == 'seq':
            cur = next_state
            for elem in reversed(node[1]):
                cur = compile_ast(elem, cur)
            return cur
        elif tag == 'alt':
            branches = node[1]
            if len(branches) == 1:
                return compile_ast(branches[0], next_state)
            rest = compile_ast(('alt', branches[1:]), next_state)
            first = compile_ast(branches[0], next_state)
            return new_state({'type': 'split', 'alt1': first, 'alt2': rest})
        elif tag == 'quant':
            elem, qt = node[1], node[2]
            if qt == '?':
                elem_start = compile_ast(elem, next_state)
                return new_state({'type': 'split', 'alt1': elem_start, 'alt2': next_state})
            elif qt == '*':
                split = new_state({'type': 'split', 'alt1': -1, 'alt2': next_state})
                elem_start = compile_ast(elem, split)
                states[split]['alt1'] = elem_start
                return split
            elif qt == '+':
                loop_split = new_state({'type': 'split', 'alt1': -1, 'alt2': next_state})
                loop_elem = compile_ast(elem, loop_split)
                states[loop_split]['alt1'] = loop_elem
                first_elem = compile_ast(elem, loop_split)
                return first_elem
        elif tag == 'char':
            c = node[1]
            return new_state({'type': 'char', 'pred': lambda ch, c=c: ch == c, 'next': next_state})
        elif tag == 'dot':
            return new_state({'type': 'char', 'pred': lambda ch: True, 'next': next_state})
        elif tag == 'class':
            items, negated = node[1], node[2]
            pred = make_class_pred(items, negated)
            return new_state({'type': 'char', 'pred': pred, 'next': next_state})
        elif tag == 'group':
            return compile_ast(node[1], next_state)
        elif tag == 'start_assert':
            return new_state({'type': 'assert_start', 'next': next_state})
        elif tag == 'end_assert':
            return new_state({'type': 'assert_end', 'next': next_state})
        else:
            raise ValueError(f"Unknown node: {tag}")

    match_state = new_state({'type': 'match'})
    start
